# o6_8 - Anhäufungen bei Kartoffeln (AH)
# Kapitel 4.2 des Maßnahmeninformationsblatts und SRL 2.8 (Anhäufungen bei Kartoffeln).
package oepul.o6_8

ridges(p) := object.get(p, ["oepul_o6_8", "potato_ridges"], {})

ah_check(p, field) := object.get(ridges(p), field, null)

parcel_violations contains violation("o6_8.ah.ridges_max_2m", p, "AH", sprintf("Abstand der Anhäufungen %v m überschreitet 2 m.", [ah_check(p, "interval_max_m")])) if {
	some p in parcels
	has_code(p, "AH")
	ah_check(p, "interval_max_m") > params.ah_max_ridge_interval_m
}

parcel_violations contains violation("o6_8.ah.ridges_max_2m", p, "AH", "Anhäufungen sind in den Rinnen der Anpflanzdämme (ausgenommen Fahrgassen) anzulegen.") if {
	some p in parcels
	has_code(p, "AH")
	ah_check(p, "in_furrows_except_tramlines") == false
}

seed_potato_row_omission_permitted(p) if {
	usage(p) == "Saatkartoffeln"
	ah_check(p, "omission_necessary_weed_control_or_safety") == true
}

parcel_violations contains violation("o6_8.ah.seed_potato_every_4th_row", p, "AH", "Verzicht auf Anhäufungen in jeder 4. Reihe nur im Saatkartoffelbau bei Erforderlichkeit (mechanische Unkrautkontrolle, Schutz arbeitender Personen).") if {
	some p in parcels
	has_code(p, "AH")
	ah_check(p, "every_4th_row_omitted") == true
	not seed_potato_row_omission_permitted(p)
}

parcel_violations contains violation("o6_8.ah.created_by_planter", p, "AH", "Anhäufungen sind mittels technischer Einrichtung am Legegerät bzw. bei abgesetztem Legeverfahren zeitnah mit der Dammfräse zu erzeugen.") if {
	some p in parcels
	has_code(p, "AH")
	ah_check(p, "created_by_planter_or_prompt_ridger") == false
}

parcel_violations contains violation("o6_8.ah.distinct_effective_ridges", p, "AH", "Das Gerät ist so einzustellen, dass deutliche, wirksame Erdanhäufungen entstehen.") if {
	some p in parcels
	has_code(p, "AH")
	ah_check(p, "distinct_effective_ridges") == false
}

parcel_violations contains violation("o6_8.ah.maintain_until_haulm_reduction", p, "AH", "Anhäufungen sind zumindest bis zur Krautminderung beizubehalten.") if {
	some p in parcels
	has_code(p, "AH")
	ah_check(p, "maintained_until_haulm_reduction") == false
}

# Erneuerung im Rahmen der Unkrautbekämpfung oder nach Regenereignissen ist zulässig
# und daher kein Verstoß gegen die Beibehaltungspflicht.
ah_renewal_permitted(reason) if reason in {"weed_control", "rain_event"}

# o6_8 - Begrünte Abflusswege (BAW)
# Kapitel 4.3, 5 und 6 des Maßnahmeninformationsblatts, SRL 2.8 und Anhang F
# (Gebietsabgrenzung der Erosions-Eintragspfade nach Katastralgemeinden).
package oepul.o6_8

baw(p) := object.get(p, ["oepul_o6_8", "baw"], {})

baw_field(p, f) := object.get(baw(p), f, null)

# --- Gebietskulisse Anhang F -----------------------------------------------

anhang_f_kg_nrs := {r.kg_nr | some r in data.o6_8.anhang_f_erosion_pathway_kgs.rows}

kg_in_anhang_f(kg_nr) if kg_nr in anhang_f_kg_nrs

parcel_violations contains violation("o6_8.baw.anhang_f_area", p, "BAW", sprintf("Katastralgemeinde %v liegt nicht in der Gebietsabgrenzung für Begrünte Abflusswege (Anhang F).", [parcel_location(p).kg_nr])) if {
	some p in parcels
	has_code(p, "BAW")
	parcel_location(p).kg_nr != null
	not kg_in_anhang_f(parcel_location(p).kg_nr)
}

# --- Lage auf dem Erosions-Eintragspfad ------------------------------------

baw_path_area_ha(p) := baw_field(p, "erosion_path_area_ha")

baw_path_share(p) := s if {
	s := baw_field(p, "erosion_path_share")
	s != null
} else := baw_path_area_ha(p) / parcel_area(p) if {
	baw_path_area_ha(p) != null
	parcel_area(p) > 0
}

parcel_violations contains violation("o6_8.baw.erosion_path_quarter_share", p, "BAW", sprintf("Nur %v des Schlages liegen auf einem ausgewiesenen Erosions-Eintragspfad (mind. ein Viertel erforderlich).", [baw_path_share(p)])) if {
	some p in parcels
	has_code(p, "BAW")
	baw_path_share(p) < params.baw_min_erosion_path_share
}

# --- Höchstausmaß: vierfache Eintragspfadfläche ----------------------------

baw_max_area_ha(path_area_ha) := path_area_ha * rate_table.baw_max_factor_of_erosion_path_area

# Hinweis zur Antragstellung: der BAW-Schlag darf höchstens das Vierfache des
# Eintragspfades ausmachen; die Prämie wird höchstens für diese Fläche gewährt.
application_notices contains violation("o6_8.baw.max_four_times_erosion_path", p, "BAW", sprintf("Mit BAW beantragte Fläche %v ha übersteigt das Vierfache des Eintragspfades (%v ha).", [parcel_area(p), baw_max_area_ha(baw_path_area_ha(p))])) if {
	some p in parcels
	has_code(p, "BAW")
	baw_path_area_ha(p) != null
	parcel_area(p) > baw_max_area_ha(baw_path_area_ha(p))
}

# Prämienfähige BAW-Fläche: höchstens 4-fache Eintragspfadfläche, abzüglich
# GLÖZ-4-Pufferstreifen und (bis 2024) GLÖZ-8-Stilllegungsanteil.
baw_gloez_excluded_ha(p) := object.get(baw(p), "gloez4_buffer_area_ha", 0) + gloez8_part(p)

gloez8_part(p) := object.get(baw(p), "gloez8_fallow_area_ha", 0) if {
	year <= params.baw_gloez8_npf_credit_until_year
} else := 0

baw_eligible_area_ha(p) := max([0, min([parcel_area(p), baw_max_area_ha(baw_path_area_ha(p))]) - baw_gloez_excluded_ha(p)]) if {
	baw_path_area_ha(p) != null
} else := max([0, parcel_area(p) - baw_gloez_excluded_ha(p)])

# --- Anlage ----------------------------------------------------------------

baw_new_sowing(p) if baw_field(p, "existing_stand_retained") != true

parcel_violations contains violation("o6_8.baw.sowing_by_15_may", p, "BAW", "Einsaat der Begrünungsmischung hat bis spätestens 15. Mai des Kalenderjahres zu erfolgen.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_new_sowing(p)
	d := baw_field(p, "sowing_date")
	d != null
	after(d, ymd(date_year(d), params.baw_sowing_deadline_mmdd))
}

parcel_violations contains violation("o6_8.baw.sowing_by_15_may", p, "BAW", "Neueinsaat muss eine winterharte Begrünungsmischung sein.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_new_sowing(p)
	baw_field(p, "winter_hardy_mixture") == false
}

parcel_violations contains violation("o6_8.baw.sowing_by_15_may", p, "BAW", sprintf("Leguminosenanteil der Neueinsaat %v %% (muss unter 50 %% liegen).", [baw_field(p, "legume_share_percent")])) if {
	some p in parcels
	has_code(p, "BAW")
	baw_new_sowing(p)
	baw_field(p, "legume_share_percent") >= params.baw_max_legume_share_percent_new_sowing
}

parcel_violations contains violation("o6_8.baw.existing_stand_without_resowing", p, "BAW", "Ohne Neueinsaat kann nur ein bestehender Grünbrache- oder Feldfutterbestand belassen werden.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_field(p, "existing_stand_retained") == true
	not baw_field(p, "existing_stand_type") in {"gruenbrache", "feldfutter"}
}

# --- Umbruch ---------------------------------------------------------------

# Bei lagegenauer Übernahme zählt das Anlagejahr des Vorbewirtschafters.
baw_establishment_year(p) := baw_field(p, "establishment_year")

baw_earliest_ploughing_date(p) := ymd(baw_establishment_year(p) + 1, params.baw_earliest_ploughing_mmdd)

parcel_violations contains violation("o6_8.baw.ploughing_earliest_15_sep_year2", p, "BAW", sprintf("Umbruch am %v vor dem frühestmöglichen Termin %v.", [baw_field(p, "ploughing_date"), baw_earliest_ploughing_date(p)])) if {
	some p in parcels
	has_code(p, "BAW")
	baw_field(p, "ploughing_date") != null
	baw_establishment_year(p) != null
	date_ns(baw_field(p, "ploughing_date")) < date_ns(baw_earliest_ploughing_date(p))
}

# Für den abgebenden Betrieb gilt die Flächenweitergabe als Verlust der Verfügungsgewalt
# (ohne Rückzahlungsverpflichtung); der lagegenau weiterführende Folgebetrieb übernimmt
# das Anlagejahr des Vorbewirtschafters.
baw_transfer_consequence(role) := "loss_of_disposal_no_repayment" if {
	role == "transferring_holder"
} else := "establishment_year_of_previous_holder_applies" if {
	role == "successor_continuing_in_place"
}

# --- Betriebsmitteleinsatz -------------------------------------------------

baw_inputs_used(p) if baw_field(p, "psm_used_since_first_declaration") == true

baw_inputs_used(p) if baw_field(p, "fertilized_since_first_declaration") == true

baw_inputs_used(p) if object.get(p, ["operations", "psm_used"], false) == true

baw_inputs_used(p) if object.get(p, ["operations", "fertilizer", "mineral_n_kg_per_ha"], 0) > 0

baw_inputs_used(p) if object.get(p, ["operations", "fertilizer", "organic_n_kg_per_ha"], 0) > 0

parcel_violations contains violation("o6_8.baw.no_psm_no_fertilizer", p, "BAW", "Kein Einsatz von Pflanzenschutz- und Düngemitteln ab 1. Jänner des Jahres der ersten Angabe als BAW bis zum Umbruch.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_inputs_used(p)
}

# --- Pflege und Nutzung ----------------------------------------------------

baw_mowing_gap_breached(p) if {
	first := baw_field(p, "first_declared_year")
	first != null
	first <= year - 1
	last := baw_field(p, "last_mowing_or_mulching_year")
	last != null
	year - last >= params.baw_mowing_interval_years
}

baw_mowing_gap_breached(p) if {
	first := baw_field(p, "first_declared_year")
	first != null
	first <= year - 1
	baw_field(p, "last_mowing_or_mulching_year") == null
	baw_field(p, "mowing_records_complete") == true
}

parcel_violations contains violation("o6_8.baw.mow_or_mulch_every_second_year", p, "BAW", "Mahd oder Häckseln mindestens einmal jedes zweite Jahr erforderlich.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_mowing_gap_breached(p)
}

parcel_violations contains violation("o6_8.baw.no_grazing_no_threshing", p, "BAW", "Beweidung und Drusch sind auf begrünten Abflusswegen nicht erlaubt.") if {
	some p in parcels
	has_code(p, "BAW")
	some f in ["grazed", "threshed"]
	baw_field(p, f) == true
}

parcel_violations contains violation("o6_8.baw.green_cover_maintained", p, "BAW", "Die Begrünung muss jedenfalls erhalten bleiben.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_field(p, "green_cover_maintained") == false
}

# --- Förderfähigkeit -------------------------------------------------------

parcel_violations contains violation("o6_8.baw.not_eligible_grassland_2020", p, "BAW", "Ackerflächen, die im MFA-Flächen 2020 als Grünland beantragt waren, sind nicht als BAW förderfähig.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_field(p, "grassland_in_mfa_2020") == true
}

baw_npf_no_premium(p) if {
	baw_field(p, "npf_code") == true
	year <= params.baw_gloez8_npf_credit_until_year
}

other_measures_on_parcel(p) := {m | some m in object.get(p, ["oepul_o6_8", "other_measures_on_parcel"], [])}

# Zulässig ist nur die Abgeltung der Landschaftselemente in UBB (1A) bzw. BIO (1B).
baw_other_measure_conflicts(p) := {m |
	some m in other_measures_on_parcel(p)
	not m in {"1A_LSE", "1B_LSE"}
}

parcel_violations contains violation("o6_8.premium.baw_no_other_measure", p, "BAW", sprintf("BAW ist auf der Einzelfläche mit keiner anderen Maßnahme kombinierbar (beantragt: %v).", [baw_other_measure_conflicts(p)])) if {
	some p in parcels
	has_code(p, "BAW")
	count(baw_other_measure_conflicts(p)) > 0
}

# --- Anrechnung als Biodiversitätsfläche (UBB/BIO) --------------------------

parcel_violations contains violation("o6_8.baw.counts_as_div_ubb_bio", p, "BAW", "Anrechnung als DIV nur bei Teilnahme an UBB oder BIO und Schlagnutzung Grünbrache oder Sonstiges Feldfutter.") if {
	some p in parcels
	has_code(p, "BAW")
	baw_field(p, "div_code") == true
	not baw_div_credit_allowed(p)
}

baw_div_credit_allowed(p) if {
	some m in {"1A", "1B"}
	m in participating_measures
	usage(p) in {"Grünbrache", "Sonstiges Feldfutter"}
}

# --- Umwandlung in Naturschutz / Ergebnisorientierte Bewirtschaftung ---------

baw_conversion_allowed(target_measure, application_date) if {
	measure_switch_allowed("8_BAW", target_measure, application_date)
}

# o6_8 - teilnahmefähige Kulturen je erosionsminderndem Verfahren
# Kapitel 7 des Maßnahmeninformationsblatts, Tabelle in data.o6_8.eligible_crops.
package oepul.o6_8

ms_ds_crop_entry(name) := e if {
	some e in crop_lists.ms_ds
	e.schlagnutzungsart == name
}

us_entry_year_ok(e) if e.from_year == null

us_entry_year_ok(e) if {
	e.from_year != null
	year >= e.from_year
}

baw_new_sowing_ok(_, e) if e.new_sowing_allowed == true

baw_new_sowing_ok(p, e) if {
	e.new_sowing_allowed == false
	object.get(p, ["oepul_o6_8", "baw", "existing_stand_retained"], false) == true
}

crop_eligible_for_code(p, "MS") if ms_ds_crop_entry(usage(p))

crop_eligible_for_code(p, "DS") if {
	e := ms_ds_crop_entry(usage(p))
	e.ds == true
}

crop_eligible_for_code(p, "AH") if {
	some e in crop_lists.ah
	e.schlagnutzungsart == usage(p)
}

crop_eligible_for_code(p, "US") if {
	some e in crop_lists.us
	e.schlagnutzungsart == usage(p)
	us_entry_year_ok(e)
}

crop_eligible_for_code(p, "BAW") if {
	some e in crop_lists.baw
	e.schlagnutzungsart == usage(p)
	baw_new_sowing_ok(p, e)
}

crop_rule_id := {
	"MS": "o6_8.crops.ms_ds_list",
	"DS": "o6_8.crops.ms_ds_list",
	"AH": "o6_8.crops.ah_list",
	"US": "o6_8.crops.us_list",
	"BAW": "o6_8.crops.baw_list",
}

parcel_violations contains violation(crop_rule_id[c], p, c, sprintf("Schlagnutzungsart %v ist für Code %v nicht teilnahmefähig.", [usage(p), c])) if {
	some p in parcels
	some c in codes(p)
	c in all_codes
	not crop_eligible_for_code(p, c)
}

parcel_violations contains violation("o6_8.application.codes_required", p, c, sprintf("Unbekannter Maßnahmencode %v; zulässig sind MS, DS, AH, BAW, US.", [c])) if {
	some p in parcels
	some c in codes(p)
	not c in all_codes
}

# Kartoffeln können nur mittels Mulchsaat angebaut werden (Kapitel 7).
potato_only_ms(p) if ms_ds_crop_entry(usage(p)).only_ms == true

# Erosionsgefährdete Kultur im Sinne von MS/DS (für Querverweise UBB/BIO).
erosion_prone_crop(p) if ms_ds_crop_entry(usage(p))

# ÖPUL 2023 - allgemeine Teilnahmebedingungen mit Bezug zu o6_8
# Förderwerbende Personen, Betriebsmindestgröße, Vertragszeitraum,
# Antragstellung, Flächenabgänge, Maßnahmenübernahme, Auszahlung,
# Obergrenzen, Modulation und Sanktionsstufen.
package oepul.o6_8

# ---------------------------------------------------------------------------
# Vertragszeitraum und Antragstellung
# ---------------------------------------------------------------------------

contract_start_year := object.get(o68, "contract_start_year", null)

contract_period(start_year) := cp if {
	some cp in params.contract_periods
	cp.start_year == start_year
}

contract_duration_years(start_year) := contract_period(start_year).years

contract_start_valid if contract_period(contract_start_year)

contract_active if {
	contract_start_valid
	year >= contract_start_year
	date_ns(ymd(year, "12-31")) <= date_ns(params.contract_end)
}

application_deadline(start_year) := ymd(start_year - 1, "12-31")

application_timely if {
	on_or_before(o68.application_submitted_date, application_deadline(contract_start_year))
}

entry_year_allowed(start_year) if start_year <= params.last_entry_year

farm_violations contains farm_violation("o6_8.contract.duration", "Vertragsbeginn muss 01.01.2023, 01.01.2024 oder 01.01.2025 sein (Vertragsende 31.12.2028).") if {
	contract_start_year != null
	not contract_start_valid
}

farm_violations contains farm_violation("o6_8.application.last_entry_2025", "Letzter Einstieg in die Maßnahme ist das Förderjahr 2025 (Beantragung bis 31.12.2024).") if {
	contract_start_year != null
	not entry_year_allowed(contract_start_year)
}

farm_violations contains farm_violation("o6_8.application.deadline_31_dec", "Maßnahmenantrag muss bis 31.12. vor Vertragsbeginn eingereicht werden.") if {
	contract_start_year != null
	object.get(o68, "application_submitted_date", null) != null
	not application_timely
}

# Folge der Nichterfüllung von Förder- bzw. Zugangsvoraussetzungen (SRL 1.12.1.1).
access_failure_consequence := "no_contract" if {
	year == contract_start_year
} else := "no_premium_for_year"

# ---------------------------------------------------------------------------
# Förderwerbende Personen, Lage, Betriebsmindestgröße
# ---------------------------------------------------------------------------

applicant := object.get(oepul, "applicant", {})

applicant_type_allowed if applicant.legal_form in general.applicant_types_allowed

applicant_public_share_ok if {
	object.get(applicant, "public_body_share_percent", 0) <= general.max_public_body_share_percent
}

applicant_eligible if {
	applicant_type_allowed
	applicant_public_share_ok
	applicant.is_active_farmer == true
}

# o6_8 ist nicht unter den Maßnahmen, an denen Gebietskörperschaften teilnehmen dürfen.
public_body_exempt_for_o6_8 if "8" in general.public_body_exempt_measures

farm_violations contains farm_violation("gen.applicant.eligible_persons", "Förderwerbende Person erfüllt die Voraussetzungen (Rechtsform, Beteiligung Gebietskörperschaften <= 25 %, aktiver Landwirt) nicht.") if {
	count(applicant) > 0
	not applicant_eligible
}

first_participation_year := object.get(oepul, "first_participation_year", null)

min_farm_size_required if year == first_participation_year

min_farm_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= general.min_farm_size.protected_cultivation_ha
}

min_farm_size_met if {
	object.get(input, ["land", "total_area_ha"], 0) >= general.min_farm_size.agricultural_area_ha
}

farm_violations contains farm_violation("gen.min_farm_size.first_year", "Im ersten ÖPUL-Teilnahmejahr sind mindestens 0,50 ha geschützter Anbau oder 1,50 ha landwirtschaftliche Fläche erforderlich.") if {
	min_farm_size_required
	not min_farm_size_met
}

parcel_in_austria(p) if parcel_location(p).country == "AT"

# ---------------------------------------------------------------------------
# Mindestbewirtschaftung und Förderfähigkeit von Flächen
# ---------------------------------------------------------------------------

is_fodder_crop(p) if usage(p) in {x | some x in definitions.ackerfutter}

# BAW-Flächen sind von den Mindestbewirtschaftungskriterien ausgenommen.
min_management_category(p) := "exempt_baw" if {
	has_code(p, "BAW")
} else := "fodder" if {
	is_fodder_crop(p)
} else := "arable"

harvested_share(p) := object.get(p, ["oepul_o6_8", "harvest", "harvested_share_percent"], null)

harvest_obligation_met(p) if harvested_share(p) >= general.min_harvest_share_percent

harvest_obligation_met(p) if harvest_obligation_waived(p)

harvest_obligation_breached(p) if {
	min_management_category(p) == "arable"
	harvested_share(p) != null
	not harvest_obligation_met(p)
}

national_park_excluded(p) if {
	np := parcel_location(p).national_park
	np in {x | some x in general.national_parks_without_area_premiums}
}

national_park_excluded(p) if {
	np := parcel_location(p).national_park
	np != null
	object.get(p, ["oepul_o6_8", "location", "national_park_relevant_obligations"], false) == true
}

op_code_set(p) if {
	some c in object.get(p, ["oepul_o6_8", "op_codes"], [])
	c in {x | some x in params.op_codes_without_o6_8_premium}
}

# Gründe, aus denen auf einem Schlag keine o6_8-Prämie gewährt wird.
exclusion_reasons := {
	"op_code", "outside_austria", "national_park", "trial_area_vf", "public_funding_overlap",
	"harvest_obligation_not_met", "commitment_not_fulfilled_whole_year", "not_eligible_land_use",
}

parcel_exclusions(p) := {r | some r in exclusion_reasons; excluded_for(p, r)}

excluded_for(p, "op_code") if op_code_set(p)

excluded_for(p, "outside_austria") if not parcel_in_austria(p)

excluded_for(p, "national_park") if national_park_excluded(p)

excluded_for(p, "trial_area_vf") if {
	object.get(p, ["oepul_o6_8", "trial_area_vf"], false) == true
}

excluded_for(p, "public_funding_overlap") if {
	object.get(p, ["oepul_o6_8", "public_funding_overlap"], false) == true
}

excluded_for(p, "harvest_obligation_not_met") if harvest_obligation_breached(p)

excluded_for(p, "commitment_not_fulfilled_whole_year") if {
	object.get(p, ["oepul_o6_8", "transferred_without_continuation"], false) == true
}

excluded_for(p, "not_eligible_land_use") if {
	p.land_use != "arable"
}

# Pflicht zur Vergabe eines OP-Codes, wenn ein Ausschlussgrund vorliegt, aber kein OP-Code gesetzt ist.
parcel_violations contains violation("gen.op_code.mandatory", p, null, "Code OP bzw. maßnahmenbezogener OP-Code ist zu vergeben (z. B. Ernteverpflichtung nicht erfüllt).") if {
	some p in parcels
	count(codes(p)) > 0
	some reason in parcel_exclusions(p)
	reason in {"harvest_obligation_not_met", "public_funding_overlap", "commitment_not_fulfilled_whole_year"}
	not op_code_set(p)
}

# ---------------------------------------------------------------------------
# Flächenänderungen, Ausstieg, Übernahme, Umwandlung
# ---------------------------------------------------------------------------

# o6_8-Flächen sind an die jährlich verfügbaren Flächen gebunden (SRL 1.7.2.5).
area_annually_variable if "8" in general.annually_variable_area_measures

# o6_8 unterliegt keiner Beschränkung der Prämienfähigkeit von Flächenzugängen (SRL 1.7.2.4).
area_increase_premium_restricted if "8" in general.area_increase_restricted_measures

area_reduction_tolerance_ha(previous_area_ha) := max([
	general.area_reduction_tolerance.min_ha_always,
	min([previous_area_ha * general.area_reduction_tolerance.max_share, general.area_reduction_tolerance.max_ha]),
])

area_reduction_repayment_applies(previous_area_ha, current_area_ha) if {
	not area_annually_variable
	previous_area_ha - current_area_ha > area_reduction_tolerance_ha(previous_area_ha)
}

exit_year := object.get(o68, "exit_year", null)

exit_reason := object.get(o68, "exit_reason", null)

repayment_free_exit_reasons := {"loss_of_disposal", "revision_clause", "permanent_circumstances_reported"}

early_exit_repayment_required if {
	exit_year != null
	exit_year <= 2028
	not exit_reason in repayment_free_exit_reasons
}

farm_transfer_continuation_required if object.get(o68, "farm_handover_to_successor", false) == true

missing_payment_application_no_premium if object.get(o68, "payment_application_submitted", true) == false

missing_payment_application_ends_commitment if {
	missing_payment_application_no_premium
	object.get(o68, "late_payment_application_within_one_year", false) == false
}

takeover_special_year(y) if y in {2023, 2028}

takeover_deadline(y) := ymd(y, general.takeover.deadline_mmdd_2023_2028) if {
	takeover_special_year(y)
} else := ymd(y, general.takeover.deadline_mmdd)

takeover_allowed(takeover_date, taken_over_area_ha, expansion_area_ha) if {
	on_or_before(takeover_date, takeover_deadline(date_year(takeover_date)))
	expansion_area_ha <= taken_over_area_ha * general.takeover.max_expansion_share
}

measure_switch_allowed(from_measure, to_measure, application_date) if {
	from_measure == "8_BAW"
	to_measure in {x | some x in params.baw_conversion_targets}
	on_or_before(application_date, params.baw_conversion_deadline)
}

# ---------------------------------------------------------------------------
# Auszahlung, Obergrenzen, Modulation, Sanktionen
# ---------------------------------------------------------------------------

payment_deadline(y) := ymd(y + 1, general.payment.due_mmdd_following_year)

max_advance_payment_eur(expected_eur) := expected_eur * general.payment.max_advance_share

payout_may_be_withheld(amount_eur) if amount_eur <= general.payment.min_payout_eur

area_cap_eur_per_ha(y) := c.eur_per_ha if {
	some c in general.area_payment_caps
	c.scope == "standard"
	year_in_range(c, y)
}

modulation_bracket_upper(b, total_ha) := min([b.to_ha, total_ha]) if {
	b.to_ha != null
} else := total_ha

modulation_factor(total_ha) := 1 if {
	total_ha <= 0
} else := f if {
	weighted := sum([part |
		some b in general.modulation_brackets
		portion := max([0, modulation_bracket_upper(b, total_ha) - b.from_ha])
		part := portion * b.factor
	])
	f := weighted / total_ha
}

sanction_stage(stage, y) := s if {
	some s in general.sanction_stages
	s.stage == stage
	year_in_range(s, y)
}

reduction_order := general.multiple_reduction_order

# o6_8 - Mulchsaat (MS), Direktsaat und Strip-Till (DS)
# Kombinationsverpflichtung, Vorfrucht-Begrünung und Verfahrensdefinitionen
# gemäß Kapitel 3.2 und 4.1 des Maßnahmeninformationsblatts und SRL 2.8.
package oepul.o6_8

has_ms_or_ds(p) if has_code(p, "MS")

has_ms_or_ds(p) if has_code(p, "DS")

# --- Kombinationsverpflichtung (Zugangsvoraussetzung) ----------------------

combination_obligation_applies if {
	some p in parcels
	has_ms_or_ds(p)
}

combination_obligation_met if {
	some m in params.combination_obligation.required_any_of_measures
	m in participating_measures
}

farm_violations contains farm_violation("o6_8.combination.ms_ds_requires_catch_crop_measure", "MS/DS erfordern die zeitgleiche Teilnahme an Zwischenfruchtanbau (6) oder System Immergrün (7).") if {
	combination_obligation_applies
	not combination_obligation_met
}

# --- Vorangehende Begrünung -------------------------------------------------

preceding(p) := object.get(p, ["oepul_o6_8", "preceding_catch_crop"], {})

preceding_variant_ok(r, _) if count(r.variants) == 0

preceding_variant_ok(r, pc) if object.get(pc, "variant", null) in r.variants

preceding_overwinter_ok(r, _) if r.requires_overwintering == false

preceding_overwinter_ok(r, pc) if {
	r.requires_overwintering == true
	object.get(pc, "overwintering", false) == true
}

# Nach Ende des Immergrün-Vertrags (Wechsel in Zwischenfruchtanbau) ist MS/DS
# nach Immergrün-Zwischenfrüchten nicht mehr prämienfähig.
preceding_scheme_active(r) if r.scheme != "oepul2023_immergruen"

preceding_scheme_active(r) if {
	r.scheme == "oepul2023_immergruen"
	"7" in participating_measures
}

preceding_catch_crop_valid(p) if {
	pc := preceding(p)
	some r in params.preceding_catch_crop
	r.scheme == object.get(pc, "scheme", null)
	year_in_range(r, year)
	preceding_variant_ok(r, pc)
	preceding_overwinter_ok(r, pc)
	preceding_scheme_active(r)
}

parcel_violations contains violation("o6_8.ms_ds.preceding_catch_crop", p, c, "MS/DS nur im Anschluss an ZWF-Varianten 2, 4, 5, 6 (ÖPUL 2023), ÖPUL-2015-Varianten 4, 5, 6 (2023), GLÖZ-8-NPF-Varianten 2, 4, 5, 6 (MFA 2025) oder überwinternde Immergrün-Zwischenfrüchte prämienfähig.") if {
	some p in parcels
	some c in codes(p)
	c in {"MS", "DS"}
	not preceding_catch_crop_valid(p)
}

# --- Mulchsaat ---------------------------------------------------------------

tillage(p) := object.get(p, ["oepul_o6_8", "tillage"], {})

main_crop_sowing_date(p) := object.get(p, ["oepul_o6_8", "main_crop_sowing_date"], null)

inverting_tillage(p) if object.get(tillage(p), "inverting_or_deep_mixing", false) == true

inverting_tillage(p) if object.get(p, ["operations", "tillage_type"], null) == "plough"

parcel_violations contains violation("o6_8.ms.no_inverting_tillage", p, c, "Wendende und tief mischende Bodenbearbeitung ist bei MS/DS unzulässig.") if {
	some p in parcels
	some c in codes(p)
	c in {"MS", "DS"}
	inverting_tillage(p)
}

parcel_violations contains violation("o6_8.ms.definition_flat_non_inverting", p, "MS", "Bei Mulchsaat muss Pflanzenmulch der Zwischenfrucht an der Oberfläche verbleiben.") if {
	some p in parcels
	has_code(p, "MS")
	object.get(tillage(p), "plant_mulch_on_surface", true) == false
}

deep_loosening_permitted(p) if {
	object.get(tillage(p), "deep_loosening", false) == true
	object.get(tillage(p), "deep_loosening_cover_preserved", false) == true
}

parcel_violations contains violation("o6_8.ms.deep_loosening_cover_preserved", p, c, "Tiefenlockerung nur mit maßgeblichem Erhalt der Begrünungskultur zulässig.") if {
	some p in parcels
	some c in codes(p)
	c in {"MS", "DS"}
	object.get(tillage(p), "deep_loosening", false) == true
	not deep_loosening_permitted(p)
}

ms_days_first_tillage_to_sowing(p) := days_between(tillage(p).first_tillage_date, main_crop_sowing_date(p))

parcel_violations contains violation("o6_8.ms.max_4_weeks_tillage_to_sowing", p, "MS", sprintf("Zwischen erster Bodenbearbeitung und Anbau liegen %v Tage (max. 28).", [ms_days_first_tillage_to_sowing(p)])) if {
	some p in parcels
	has_code(p, "MS")
	ms_days_first_tillage_to_sowing(p) > params.ms_max_days_first_tillage_to_sowing
}

# --- Direktsaat / Strip-Till ------------------------------------------------

ds_method(p) := object.get(tillage(p), "ds_method", "direct_seeding")

parcel_violations contains violation("o6_8.ds.definition_direct_seeding", p, "DS", "Direktsaat: keine vollflächige Bodenbearbeitung, nur Einsaat im Schlitzverfahren direkt in den Begrünungsbestand.") if {
	some p in parcels
	has_code(p, "DS")
	ds_method(p) == "direct_seeding"
	object.get(tillage(p), "full_surface_tillage", false) == true
}

parcel_violations contains violation("o6_8.ds.definition_direct_seeding", p, "DS", "Direktsaat erfordert Einsaat mittels Schlitzverfahren.") if {
	some p in parcels
	has_code(p, "DS")
	ds_method(p) == "direct_seeding"
	object.get(tillage(p), "slot_seeding", true) == false
}

parcel_violations contains violation("o6_8.ds.definition_strip_till", p, "DS", "Strip-Till: Bearbeitung nur streifenförmig in der Saatreihe, Zwischenfrucht bzw. Pflanzenreste zwischen den Streifen erhalten.") if {
	some p in parcels
	has_code(p, "DS")
	ds_method(p) == "strip_till"
	strip_till_breach(p)
}

strip_till_breach(p) if object.get(tillage(p), "strip_only_in_seed_row", true) == false

strip_till_breach(p) if object.get(tillage(p), "cover_residues_retained_between_strips", true) == false

strip_till_breach(p) if object.get(tillage(p), "full_surface_tillage", false) == true

# --- Codekombinationen auf der Einzelfläche ----------------------------------

ms_ds_ah_conflict(p) if {
	has_ms_or_ds(p)
	has_code(p, "AH")
}

parcel_violations contains violation("o6_8.premium.ms_ds_ah_not_combinable", p, "AH", "MS/DS und AH sind auf der Einzelfläche nicht prämienfähig kombinierbar.") if {
	some p in parcels
	ms_ds_ah_conflict(p)
}

allowed_code_pair(a, b) if {
	some pair in params.allowed_same_parcel_code_pairs
	{a, b} == {x | some x in pair}
}

# Explizit zulässig sind nur MS+US und DS+US; andere Mehrfachcodierungen werden als
# offene Frage gemeldet (keine Prämienwirkung, siehe notes/assumptions.md).
unlisted_code_combinations contains {"parcel_id": pid(p), "codes": [a, b]} if {
	some p in parcels
	some a in codes(p)
	some b in codes(p)
	a < b
	not allowed_code_pair(a, b)
	not {a, b} in {{"MS", "AH"}, {"DS", "AH"}}
}

# Option "Humusaufbau und Erosionsschutz in Wien": keine MS/DS-Prämie auf Wiener Flächen.
vienna_humus_option_blocks(p) if {
	"16_humus_wien" in farm_options
	parcel_location(p).federal_state == "Wien"
}

# o6_8 - Mindestteilnahme, Prämienberechnung und Gesamtentscheidung
# Kapitel 3.3 und 6 des Maßnahmeninformationsblatts, SRL 2.8 (Höhe der
# Förderung) sowie Modulation und Flächenobergrenzen (SRL 1.9.2).
package oepul.o6_8

violations := parcel_violations | farm_violations

# --- Verfahrenskonformität je Schlag und Code ------------------------------

parcel_code_violations(p, c) := {v |
	some v in parcel_violations
	v.parcel_id == pid(p)
	v.code in {c, null}
}

code_compliant(p, c) if {
	has_code(p, c)
	c in all_codes
	crop_eligible_for_code(p, c)
	count(parcel_code_violations(p, c)) == 0
	count(parcel_exclusions(p)) == 0
}

# --- Mindestteilnahme 0,10 ha ----------------------------------------------

participating_parcels contains pid(p) if {
	some p in parcels
	some c in codes(p)
	code_compliant(p, c)
}

participation_area_ha := sum([parcel_area(p) |
	some p in parcels
	pid(p) in participating_parcels
])

min_participation_met if participation_area_ha >= params.min_participation_area_ha

farm_violations contains farm_violation("o6_8.min_participation.area_0_10_ha", sprintf("Teilnahmefläche %v ha unterschreitet die jährliche Mindestteilnahme von 0,10 ha.", [participation_area_ha])) if {
	not min_participation_met
}

# Ersatzweise Erfüllung der Mindestteilnahme durch AH, BAW oder US, wenn MS/DS nicht möglich ist.
min_participation_without_ms_ds_ha := sum([parcel_area(p) |
	some p in parcels
	some c in (codes(p) & {"AH", "BAW", "US"})
	code_compliant(p, c)
])

# --- Zugangsvoraussetzungen auf Betriebsebene ------------------------------

access_blocking_rules := {
	"o6_8.contract.duration",
	"o6_8.application.last_entry_2025",
	"o6_8.application.deadline_31_dec",
	"gen.applicant.eligible_persons",
	"gen.min_farm_size.first_year",
	"o6_8.min_participation.area_0_10_ha",
}

farm_access_failures := {v.rule_id | some v in farm_violations; v.rule_id in access_blocking_rules}

farm_access_ok if {
	contract_active
	count(farm_access_failures) == 0
}

# --- Prämienfähigkeit je Code ------------------------------------------------

code_premium_blocked(_, c) if {
	c in {"MS", "DS"}
	not combination_obligation_met
}

code_premium_blocked(p, c) if {
	c in {"MS", "DS"}
	vienna_humus_option_blocks(p)
}

code_premium_blocked(p, "BAW") if baw_npf_no_premium(p)

code_premium_blocked(p, c) if {
	c in {"MS", "DS", "AH"}
	ms_ds_ah_conflict(p)
}

code_premium_eligible(p, c) if {
	farm_access_ok
	code_compliant(p, c)
	not code_premium_blocked(p, c)
}

rate(code, y) := r.eur_per_ha if {
	some r in rate_table.rates
	r.code == code
	year_in_range(r, y)
}

code_area_ha(p, c) := baw_eligible_area_ha(p) if {
	c == "BAW"
} else := parcel_area(p)

code_premium_eur(p, c) := round2(code_area_ha(p, c) * rate(c, year)) if {
	code_premium_eligible(p, c)
} else := 0

us_bio_surcharge_eur(p) := round2(parcel_area(p) * rate("US_BIO", year)) if {
	code_premium_eligible(p, "US")
	"1B" in participating_measures
} else := 0

parcel_premium_eur(p) := sum([code_premium_eur(p, c) | some c in codes(p)]) + us_bio_surcharge_eur(p)

parcel_results[pid(p)] := {
	"codes": codes(p),
	"compliant_codes": {c | some c in codes(p); code_compliant(p, c)},
	"premium_eligible_codes": {c | some c in codes(p); code_premium_eligible(p, c)},
	"exclusions": parcel_exclusions(p),
	"premium_by_code_eur": {c: code_premium_eur(p, c) | some c in codes(p)},
	"us_bio_surcharge_eur": us_bio_surcharge_eur(p),
	"premium_eur": parcel_premium_eur(p),
	"area_cap_exceeded": area_cap_exceeded(p),
} if {
	some p in parcels
	count(codes(p)) > 0
}

# --- Flächenobergrenze je Schlag ---------------------------------------------

area_cap_exceeded(p) if {
	parcel_area(p) > 0
	other := object.get(p, ["oepul_o6_8", "other_area_payments_eur_per_ha"], 0)
	(parcel_premium_eur(p) / parcel_area(p)) + other > area_cap_eur_per_ha(year)
} else := false

# --- Gesamtergebnis ------------------------------------------------------------

premium_gross_eur := round2(sum([parcel_premium_eur(p) | some p in parcels]))

farm_modulation_factor := modulation_factor(object.get(input, ["land", "total_area_ha"], 0))

premium_after_modulation_eur := round2(premium_gross_eur * farm_modulation_factor)

decision := {
	"measure": "o6_8",
	"year": year,
	"contract_active": contract_active,
	"farm_access_ok": farm_access_ok,
	"farm_access_failures": farm_access_failures,
	"access_failure_consequence": access_failure_consequence,
	"combination_obligation_applies": combination_obligation_applies,
	"combination_obligation_met": combination_obligation_met,
	"participation_area_ha": participation_area_ha,
	"min_participation_met": min_participation_met,
	"violations": violations,
	"unlisted_code_combinations": unlisted_code_combinations,
	"application_notices": application_notices,
	"parcel_results": parcel_results,
	"premium_gross_eur": premium_gross_eur,
	"modulation_factor": farm_modulation_factor,
	"premium_after_modulation_eur": premium_after_modulation_eur,
	"payment_deadline": payment_deadline(year),
}

default contract_active := false

default farm_access_ok := false

default combination_obligation_applies := false

default combination_obligation_met := false

default min_participation_met := false

# o6_8 - Untersaat (US)
# Kapitel 4.4 des Maßnahmeninformationsblatts und SRL 2.8 (Untersaaten bei
# Ackerbohne, Kürbis, Soja, Sonnenblume, ab 2025 auch Mais, Sorghum, Sudangras).
package oepul.o6_8

undersowing(p) := object.get(p, ["oepul_o6_8", "undersowing"], {})

us_field(p, f) := object.get(undersowing(p), f, null)

parcel_violations contains violation("o6_8.us.min_3_mixture_partners", p, "US", sprintf("Untersaat mit %v Mischungspartnern (mindestens 3 erforderlich).", [us_field(p, "mixture_partner_count")])) if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "mixture_partner_count") != null
	us_field(p, "mixture_partner_count") < params.us_min_mixture_partners
}

parcel_violations contains violation("o6_8.us.min_3_mixture_partners", p, "US", "Untersaat ist aktiv zwischen den Reihen der Hauptkultur anzulegen.") if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "between_rows") == false
}

us_is_winter_field_bean(p) if usage(p) == "Winterackerbohnen"

us_is_winter_field_bean(p) if us_field(p, "winter_field_bean") == true

us_latest_by_main_crop(p) := time.format([date_ns(main_crop_sowing_date(p)) + (params.us_max_days_after_main_crop_sowing * ns_per_day), "UTC", "2006-01-02"])

us_calendar_deadline(p) := ymd(date_year(us_field(p, "sowing_date")), params.us_winter_field_bean_deadline_mmdd) if {
	us_is_winter_field_bean(p)
} else := ymd(date_year(us_field(p, "sowing_date")), params.us_deadline_mmdd)

parcel_violations contains violation("o6_8.us.sowing_within_8_weeks_latest_30_june", p, "US", sprintf("Untersaat am %v später als 8 Wochen nach Anbau der Hauptkultur (%v).", [us_field(p, "sowing_date"), main_crop_sowing_date(p)])) if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "sowing_date") != null
	main_crop_sowing_date(p) != null
	days_between(main_crop_sowing_date(p), us_field(p, "sowing_date")) > params.us_max_days_after_main_crop_sowing
}

parcel_violations contains violation("o6_8.us.sowing_within_8_weeks_latest_30_june", p, "US", sprintf("Untersaat am %v nach dem spätesten Anlagetermin %v.", [us_field(p, "sowing_date"), us_calendar_deadline(p)])) if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "sowing_date") != null
	after(us_field(p, "sowing_date"), us_calendar_deadline(p))
}

parcel_violations contains violation("o6_8.us.seed_proof_if_not_visible", p, "US", "Mischungspartner am Feld nicht ersichtlich: Saatgutnachweis (Rechnung oder Etikett) erforderlich.") if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "partners_visible_in_field") == false
	us_field(p, "seed_proof_available") != true
}

parcel_violations contains violation("o6_8.us.adequate_emergence", p, "US", "Saatstärke, Anbautechnik und Anbauzeitpunkt müssen ausreichenden Feldaufgang mit Erosionsschutzwirkung gewährleisten.") if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "adequate_emergence") == false
	not us_full_coverage_waived(p)
}

parcel_violations contains violation("o6_8.us.full_coverage", p, "US", "Untersaat muss flächendeckend angelegt sein.") if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "full_coverage_achieved") == false
	not us_full_coverage_waived(p)
}

us_post_sowing_soil_or_herbicide(p) if {
	some f in ["tillage_after_sowing", "harrowing_after_sowing", "herbicide_after_sowing"]
	us_field(p, f) == true
}

parcel_violations contains violation("o6_8.us.no_tillage_no_herbicide_after_sowing", p, "US", "Nach Anlage der Untersaat bis zur Ernte der Hauptkultur keine Bodenbearbeitung (inkl. Striegeln) und kein Herbizideinsatz.") if {
	some p in parcels
	has_code(p, "US")
	us_post_sowing_soil_or_herbicide(p)
}

parcel_violations contains violation("o6_8.us.maintain_until_harvest_not_harvested", p, "US", "Untersaat muss bis zur Ernte der Hauptkultur erhalten bleiben.") if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "maintained_until_main_crop_harvest") == false
}

parcel_violations contains violation("o6_8.us.maintain_until_harvest_not_harvested", p, "US", "Mitgeerntete Untersaat gilt als Mischkultur, nicht als Untersaat.") if {
	some p in parcels
	has_code(p, "US")
	us_field(p, "harvested_with_main_crop") == true
}

# Untersaat als Zwischenfrucht für "Zwischenfruchtanbau" (6): Anlagetermin ist die
# Ernte der Hauptkultur, die vor dem verpflichtenden Anlagetermin der Variante liegen muss.
us_catch_crop_establishment_date(p) := us_field(p, "main_crop_harvest_date")

